    '-': lambda a, b: a - b,
    '*': lambda a, b: a * b,
    '/': _divide,
}


def evaluate(input_data):
    stack = []
    words = {}

    def run(token):
        if token in words:
            for sub in words[token]:
                run(sub)
        elif _is_number(token):
            stack.append(int(token))
        elif token in BINARY:
            _need(stack, 2)
